typedef unsigned int u_int;

class vector3d
{
public:
  typedef float T;
  T x, y, z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d& operator=(const vector3d& v)
  {
    x = v.x;
    y = v.y;
    z = v.z;
    return *this;
  }
};

typedef struct crashnode_t
{
  vector3d pos;
  float mag;
  float size;
  float age;
  u_int type;
  struct crashnode_t* Next;
} crashnode_s;

extern crashnode_s* CrashHead;
extern crashnode_s* CrashFreeHead;
extern float debug_reject_dist;
extern float TIMER_FrameSec;

inline float TIMER_GetFrameSec(void) { return TIMER_FrameSec; }
void set_size(crashnode_s* Ptr);

asm(".equ CrashHead,0x0048A898");
asm(".equ CrashFreeHead,0x0048A89C");
asm(".equ debug_reject_dist,0x004844C0");
asm(".equ TIMER_FrameSec,0x0045B280");
asm(".equ set_size__FP11crashnode_t,0x0036C6D0");

#define NULL 0
#define assert(c) ((void)0)

crashnode_s *crash_insert(crashnode_s *Hint, vector3d pos, float mag, u_int type)
{
	crashnode_s *Ptr;
	crashnode_s *BackPtr;
	//	u_int done = 0;
	float tmp;

	//	currentcrash++;
	//	if(currentcrash>=MAX_CRASH_NODES)
	//		currentcrash = 0;
	//  assert (!crashnodes[currentcrash].used);

	// Don't crash the game if it can't insert the crash node - rbroner (6/24/02)
	if(CrashFreeHead == NULL)
	{
		return NULL;
	}

	assert( CrashFreeHead );
	crashnode_s *node = CrashFreeHead;

	node->age = (float)TIMER_GetFrameSec();
	node->mag = mag;
	node->size= 0;
	node->pos = pos;
	node->type = type;


	set_size( node );

	if((CrashHead==NULL)||(CrashHead->pos.x >= node->pos.x))
	{
		CrashFreeHead = node->Next;
		node->Next = CrashHead;
		CrashHead = node;
		return(CrashHead);
	}

	if(Hint!=NULL)
	{
		BackPtr = Hint;
		Ptr = Hint;
	}
	else
	{
		BackPtr = CrashHead;
		Ptr = CrashHead;
	}

#if defined(TARGET_XBOX)
	int running_count = 0;

	while((Ptr!=NULL) && (Ptr->pos.x < node->pos.x) && (running_count < MAX_CRASH_NODES))
	{
		tmp = node->pos.x - Ptr->pos.x;
		if((tmp * tmp) < (debug_reject_dist * debug_reject_dist))
			return(Ptr);

		running_count++;

		BackPtr=Ptr;
		Ptr=Ptr->Next;
	}

	if(running_count == MAX_CRASH_NODES)
	{
		debug_print( "crash_insert circular list\n" );
	}
#else
	while((Ptr!=NULL) && (Ptr->pos.x < node->pos.x))
	{
		tmp = node->pos.x - Ptr->pos.x;
		if((tmp * tmp) < (debug_reject_dist * debug_reject_dist))
			return(Ptr);

		BackPtr=Ptr;
		Ptr=Ptr->Next;
	}
#endif /* TARGET_XBOX JIV DEBUG */

	if(BackPtr->Next!=NULL)
	{
		tmp = node->pos.x - BackPtr->pos.x;
		if((tmp * tmp) < (debug_reject_dist * debug_reject_dist))
			return(BackPtr);
	}

	CrashFreeHead = node->Next;
	node->Next = BackPtr->Next;
	BackPtr->Next=node;

	return( node );
}
